page='<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>P06 rib-saddle review</title><style>body{font:16px/1.5 system-ui;max-width:1150px;margin:30px auto;padding:0 24px;background:#f4f7fa;color:#213547}img{width:100%}pre{white-space:pre-wrap;font:inherit;background:white;padding:24px}table{border-collapse:collapse;width:100%;font-size:14px;background:white}td,th{padding:8px;border-bottom:1px solid #d8e0e6;text-align:left}th{background:#213547;color:white}</style><h1>P06 rib-to-saddle connection</h1><img src="../cad/Rib_Saddle_Review.png" alt="Actual carrier and transverse joint section"><h2>Full station reaction on one splice · preliminary screens</h2><table><tr><th>Side</th><th>Station</th><th>Rib</th><th>Contact mm²</th><th>Net width mm</th><th>Shear util.</th><th>Plate util.</th><th>Peel demand MPa</th></tr>'+rows+'</table><pre>'+esc(text)+'</pre></html>'
